+        return null;
+    }
+
+    @Override
+    public void releasePeriod(MediaPeriod mediaPeriod) {}
+
+    @Override
+    public void releaseSource() {}
+
+    @Override
+    public boolean canReplace() {
+        return canRetry();
+    }
