+        return System.currentTimeMillis() >= expireTimestamp;
+    }
+
+    @Override
+    public void prepareSource(ExoPlayer player, boolean isTopLevelSource, Listener listener) {
+        source.prepareSource(player, isTopLevelSource, listener);
