+    }
+
+    public DashMediaSource.Factory getLiveDashMediaSourceFactory() {
+        return new DashMediaSource.Factory(new DefaultDashChunkSource.Factory(
+                cachelessDataSourceFactory), cachelessDataSourceFactory)
